async function uploadProductPhoto(productId:string,file:File){const form=new FormData();form.set('productId',productId);form.set('photo',file);const r=await fetch('/api/menu/image',{method:'POST',body:form});const d=await r.json();if(!r.ok)throw new Error(d.error||'Photo upload failed.');}
