 const guests=Number(form.guests),validGuests=Number.isInteger(guests)&&guests>0;
 const perGuest=chosen&&validGuests?Math.ceil(chosen.price/guests):null;
 useEffect(()=>{try{const draft=parseBookingDraft(localStorage.getItem(BOOKING_DRAFT_KEY));if(draft){setPackageId(draft.packageId);setSelected(draft.selected);setStep(draft.packageId?(draft.selected?draft.step:Math.min(draft.step,2) as 1|2):1);setForm(f=>({...f,guests:draft.guests,eventType:draft.eventType,eventTime:draft.eventTime}));setHasDraft(true)}else localStorage.removeItem(BOOKING_DRAFT_KEY)}catch{}setHydrated(true)},[]);
 useEffect(()=>{if(!hydrated)return;if(!packageId&&!selected){try{localStorage.removeItem(BOOKING_DRAFT_KEY)}catch{}return}try{localStorage.setItem(BOOKING_DRAFT_KEY,serializeBookingDraft({packageId,selected,step,guests:form.guests,eventType:form.eventType,eventTime:form.eventTime}))}catch{}},[hydrated,packageId,selected,step,form.guests,form.eventType,form.eventTime]);
