 function resetDraft(){try{localStorage.removeItem(BOOKING_DRAFT_KEY)}catch{}setPackageId('');setSelected('');setStep(1);setForm({name:user?.name||'',phone:'',eventTime:'14:00',eventType:'Birthday',venue:'',guests:'50',notes:''});setError('');setHasDraft(false)}
